const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_SHARED_SECRET must be set to at least 32 characters');
const h = $input.first().json.headers || {};
const ts = String(h['x-lendloop-timestamp'] || '');
const signature = String(h['x-lendloop-signature'] || '');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
const fresh = /^\d{13}$/.test(ts) && Math.abs(Date.now() - Number(ts)) <= 5 * 60 * 1000;
const signatureValid = /^sha256=[0-9a-f]{64}$/.test(signature);
let valid = false;
if (fresh && signatureValid) {
  const expectedBytes = Buffer.from(expected, 'hex');
  const actualBytes = Buffer.from(signature.slice(7), 'hex');
  valid = actualBytes.length === expectedBytes.length && crypto.timingSafeEqual(actualBytes, expectedBytes);
}
return [{ json: { valid, event: valid ? JSON.parse(raw) : null } }];

const e = $json.event;
if (!e || typeof e.eventId !== 'string' || typeof e.recipient?.email !== 'string') {
  throw new Error('Invalid signed event payload');
}
// De-duplicate: Convex may re-send an event if our 200 response was lost.
const seen = ($getWorkflowStaticData('global').seen ||= {});
if (seen[e.eventId]) return [{ json: { duplicate: true } }];
seen[e.eventId] = Date.now();
const keys = Object.keys(seen);
if (keys.length > 500) keys.sort((x, y) => seen[x] - seen[y]).slice(0, keys.length - 500).forEach((k) => delete seen[k]);

const t = e.toolName, who = e.counterpartName, d = `${e.loan.startDate} to ${e.loan.endDate}`;
const copy = {
  request_created:  [`New request for ${t}`, `${who} would like to borrow ${t} (${d}). Open LendLoop to approve or decline.`],
  request_approved: [`Approved: ${t}`, `${who} approved your request for ${t} (${d}).`],
  request_declined: [`Declined: ${t}`, `${who} can't lend ${t} for ${d}. Try other dates or another tool.`],
  loan_returned:    [`Returned: ${t}`, `${who} marked ${t} as returned. Thanks for being a good neighbor.`],
  request_cancelled_by_borrower: [`Cancelled: ${t}`, `${who} cancelled their request for ${t} (${d}).`],
  request_cancelled_by_owner: [`Listing removed: ${t}`, `${who} removed ${t} from the board. Your pending request has been cancelled.`],
}[e.type];
if (!copy) throw new Error('Unknown event type: ' + e.type);
const msg = { to: e.recipient.email, name: e.recipient.name, subject: copy[0], body: copy[1] };
// MOCK delivery: logged only. Swap this node for Send Email / Slack / Discord using n8n credentials.
console.log('[LendLoop notification]', JSON.stringify(msg));
return [{ json: { duplicate: false, ...msg } }];
